-- ============================================
-- LUMA — Enrichissement Thématique 15 (Londres) : scénarios longs (2 des 3 ; le 15.9 avait déjà de bons embranchements)
-- ============================================

update scenarios set content = '{"characters": {"friend": "ton ami de voyage"}, "start_node": "n1", "nodes": {"n1": {"speaker": "friend", "text": "Day one, museums! Which one first, the British Museum or the Natural History Museum?", "text_fr": "Jour un, musées ! Lequel en premier, le British Museum ou le Natural History Museum ?", "choices": [{"text": "British Museum, I want to see the Rosetta Stone.", "next": "n2"}, {"text": "Natural History, I love dinosaurs!", "next": "n2b"}]}, "n2": {"speaker": "friend", "text": "(days pass) We''ve covered museums and markets. Day four, let''s do something active — Hyde Park?", "text_fr": "(les jours passent) On a fait musées et marchés. Jour quatre, faisons quelque chose d''actif — Hyde Park ?", "choices": [{"text": "Let''s rent bikes and explore the park properly.", "next": "n3"}, {"text": "Let''s just have a relaxing picnic instead.", "next": "n3b"}]}, "n2b": {"speaker": "friend", "text": "Good choice! Day four now, let''s do something active — Hyde Park?", "text_fr": "Bon choix ! Jour quatre maintenant, faisons quelque chose d''actif — Hyde Park ?", "choices": [{"text": "Let''s rent bikes and explore the park properly.", "next": "n3"}]}, "n3": {"speaker": "friend", "text": "(after biking) That was exhausting but so much fun! Day five, any requests?", "text_fr": "(après le vélo) C''était épuisant mais tellement amusant ! Jour cinq, des envies particulières ?", "choices": [{"text": "Let''s do something unplanned, wander Notting Hill.", "next": "n4"}, {"text": "Let''s find a proper afternoon tea experience.", "next": "n4b"}]}, "n3b": {"speaker": "friend", "text": "(the picnic turns lovely, unexpected sunshine) This was exactly the break we needed.", "text_fr": "(le pique-nique devient charmant, soleil inattendu) C''était exactement la pause dont on avait besoin.", "choices": [{"text": "Day five, any requests for what''s next?", "next": "n4"}]}, "n4": {"speaker": "friend", "text": "Best idea all week — this neighborhood is gorgeous!", "text_fr": "Meilleure idée de la semaine — ce quartier est magnifique !", "choices": [{"text": "Final day tomorrow — what''s left on your list?", "next": "n5"}]}, "n4b": {"speaker": "friend", "text": "This tea house is straight out of a postcard!", "text_fr": "Ce salon de thé sort tout droit d''une carte postale !", "choices": [{"text": "Final day tomorrow — what''s left on your list?", "next": "n5"}]}, "n5": {"speaker": "friend", "text": "Honestly, I just want to revisit our favorite spot from day one.", "text_fr": "Honnêtement, je veux juste revoir notre endroit préféré du premier jour.", "choices": [{"text": "That sounds perfect, a full circle to end the trip.", "next": "end_week"}]}, "end_week": {"speaker": "friend", "text": "London really has given us everything this week.", "text_fr": "Londres nous a vraiment tout donné cette semaine.", "end": true, "ending_label": "Semaine complète et mémorable 🇬🇧"}}}'::jsonb, is_playable = true
where title = 'Un séjour complet d''une semaine avec plusieurs journées thématiques'
  and theme_id = (select id from scenario_themes where position = 15 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"passerby1": "premier passant", "passerby2": "deuxième passant", "passerby3": "troisième passant"}, "start_node": "n1", "nodes": {"n1": {"speaker": "passerby1", "text": "You look a bit lost, can I help?", "text_fr": "Vous semblez un peu perdu, je peux vous aider ?", "choices": [{"text": "Yes, I''m trying to find Camden Market but I think I took a wrong turn.", "next": "n2"}, {"text": "I''m actually not sure where I am on the map at all!", "next": "n2b"}]}, "n2": {"speaker": "passerby1", "text": "Ah, you''re quite far actually. Ask that shopkeeper, she''ll know better.", "text_fr": "Ah, vous êtes assez loin en fait. Demandez à cette commerçante, elle saura mieux.", "choices": [{"text": "Thank you, I''ll ask her.", "next": "n3"}]}, "n2b": {"speaker": "passerby1", "text": "No worries, let''s figure it out together — where are you trying to go?", "text_fr": "Pas de souci, on va trouver ensemble — où essayez-vous d''aller ?", "choices": [{"text": "Camden Market, I completely lost my bearings.", "next": "n3"}]}, "n3": {"speaker": "passerby2", "text": "Camden Market? Take the tube from that station, two stops north.", "text_fr": "Camden Market ? Prenez le métro depuis cette station, deux arrêts au nord.", "choices": [{"text": "That''s much clearer now, thank you!", "next": "n4"}, {"text": "Actually, is it walkable from here instead?", "next": "n4b"}]}, "n4": {"speaker": "passerby2", "text": "You''re welcome! Enjoy the market, it''s wonderful this time of year.", "text_fr": "De rien ! Profitez bien du marché, il est magnifique à cette période.", "choices": [{"text": "I will, thanks again!", "next": "end_found"}]}, "n4b": {"speaker": "passerby2", "text": "It''s about 40 minutes on foot, a nice walk if you''re not in a rush.", "text_fr": "C''est environ 40 minutes à pied, une belle balade si vous n''êtes pas pressé.", "choices": [{"text": "I''ll walk then, I love exploring on foot.", "next": "n5"}]}, "n5": {"speaker": "passerby3", "text": "(along the way, you get slightly turned around again) Need directions again?", "text_fr": "(en chemin, vous vous perdez encore un peu) Besoin d''indications encore ?", "choices": [{"text": "Ha, yes actually! Am I close to Camden now?", "next": "end_found"}]}, "end_found": {"speaker": "passerby3", "text": "Londoners always help each other out, no worries — you''re very close now!", "text_fr": "Les Londoniens s''entraident toujours, pas de souci — vous êtes très proche maintenant !", "end": true, "ending_label": "Chemin retrouvé grâce à l''entraide de plusieurs habitants 🧭"}}}'::jsonb, is_playable = true
where title = 'Se perdre et retrouver son chemin en interagissant avec plusieurs habitants'
  and theme_id = (select id from scenario_themes where position = 15 and language_id = (select id from languages where code = 'en'));
